default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Netlogon\Parameters' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('MaximumPasswordAge', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]$ODV_domain_member_maximum_password_age)) {
    Write-Output 'Mismatch: HKLM:\SYSTEM\CurrentControlSet\Services\Netlogon\Parameters [MaximumPasswordAge]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Netlogon\Parameters')) {
    New-Item -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\Netlogon\Parameters' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Netlogon\Parameters' -Name 'MaximumPasswordAge' -Value $ODV_domain_member_maximum_password_age -PropertyType DWord -Force | Out-Null
exit 0
